function buildPlan(){const plan=[];plan.push({kind:'root',id:DATA.page.root_key,name:DATA.page.root_name,x:0,y:0,width:DATA.page.width,height:DATA.page.height,parent:'page'});plan.push({kind:'header',id:'atlas.header.instance',name:'ATLAS_PAGE_HEADER_V2 · Owner Review Index',x:64,y:64,width:2496,height:128,parent:'root'});plan.push(textPlan('authority/title','42 CURRENT ATLAS R2 PHYSICAL PAGES',64,272,1200,28,18,'700','#111827'));plan.push(textPlan('authority/status','Every row is PENDING_V0 until its own native export receives a page-scoped V0 verdict. No PASS is inherited.',64,312,1800,24,12,'400','#92400E'));plan.push(textPlan('authority/digest','Atlas page_units SHA-256 · '+DATA.atlas.page_units_sha256,64,352,1800,22,11,'400','#4B5563'));const columns=[['ORDER',64,72],['ATLAS PAGE ID',148,488],['PACKAGE',648,488],['TEMPLATE',1148,424],['PROJECTION',1584,144],['V0 STATUS',1740,160],['PHYSICAL PAGE',1912,648]];for(const [label,x,width] of columns)plan.push(textPlan('column/'+label.toLowerCase().replaceAll(' ','-'),label,x,416,width,24,10,'700','#4B5563'));for(let index=0;index<DATA.rows.length;index+=1){const row=DATA.rows[index];const y=rowY(index),id='row/'+String(index+1).padStart(2,'0'),shade=index%2===0?'#FFFFFF':'#F8FAFC';plan.push({kind:'rect',id,name:'Atlas physical page row '+row.page_order,x:64,y,width:2496,height:48,color:shade,parent:'root',row});plan.push(textPlan(id+'/page-order',row.page_order,76,y+14,56,20,10,'700'));plan.push(textPlan(id+'/atlas-page-id',row.atlas_page_id,148,y+14,488,20,9,'400'));plan.push(textPlan(id+'/package',row.package_id,648,y+14,488,20,9,'400'));plan.push(textPlan(id+'/template',row.template_id,1148,y+14,424,20,9,'400'));plan.push(textPlan(id+'/projection',row.projection_role,1584,y+14,144,20,10,'700'));plan.push(textPlan(id+'/v0-status',row.v0_status,1740,y+14,160,20,10,'700','#92400E'));plan.push(textPlan(id+'/physical-page',row.physical_page_name,1912,y+14,648,20,9,'400'));}return plan}
